#!/bin/sh
# Generated by forge. UserPromptSubmit: records the working tree at the start of
# the turn, so the Stop hook checks only work done during the turn, and resets
# the Stop block counter. Prints nothing (its output would reach Claude).
dir=$(cd "$(dirname "$0")" && pwd)
FORGE_INPUT=$(cat)
. "$dir/lib.sh"
repo_root || exit 0
mkdir -p .forge/state 2>/dev/null || exit 0
session=$(session_id)
tree_hash > ".forge/state/$session.turn" 2>/dev/null
rm -f ".forge/state/$session"
exit 0
